param([string]$DocumentPath=(Join-Path (Split-Path $PSScriptRoot -Parent) 'Chapter 3.docx'))
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
Add-Type -AssemblyName System.Drawing
$root=Split-Path $PSScriptRoot -Parent;$diagram=Join-Path $root 'Chapter 3 Diagrams';$path=(Resolve-Path -LiteralPath $DocumentPath).Path
$source=Join-Path $diagram '_Sources/03-dfd-complete-one-page.png';if(-not(Test-Path -LiteralPath $source)){throw 'Render the complete DFD first.'}
$backup=Join-Path $root ('Review Backups/dfd-one-page-'+(Get-Date -Format yyyyMMdd-HHmmss));New-Item -ItemType Directory -Path $backup -Force|Out-Null
Copy-Item -LiteralPath $path -Destination (Join-Path $backup 'Chapter 3 before one-page DFD.docx')
$work=Join-Path $backup 'Chapter 3 working.docx';Copy-Item -LiteralPath $path -Destination $work
$zip=[IO.Compression.ZipFile]::Open($work,'Update')
try{
 function ReadXml($part){$reader=[IO.StreamReader]::new($zip.GetEntry($part).Open());try{return ,([xml]$reader.ReadToEnd())}finally{$reader.Dispose()}}
 function SaveXml($part,$xml){$stream=$zip.GetEntry($part).Open();$stream.SetLength(0);$writer=[IO.StreamWriter]::new($stream,[Text.UTF8Encoding]::new($false));try{$xml.Save($writer)}finally{$writer.Dispose()}}
 function WriteBinary($part,$file){$old=$zip.GetEntry($part);if($old){$old.Delete()};$stream=$zip.CreateEntry($part).Open();try{$bytes=[IO.File]::ReadAllBytes($file);$stream.Write($bytes,0,$bytes.Length)}finally{$stream.Dispose()}}
 function TextOf($p){($p.SelectNodes('.//w:t',$ns)|ForEach-Object InnerText)-join ''}
 function TargetOf($p){$blip=$p.SelectSingleNode('.//a:blip',$ns);if(-not $blip){return ''};$rid=$blip.GetAttribute('embed',$r);$rel=$rels.Relationships.Relationship|Where-Object Id -eq $rid;return [string]$rel.Target}
 function SetText($p,[string]$value){$nodes=$p.SelectNodes('.//w:t',$ns);if(-not $nodes.Count){throw 'Paragraph template has no text node.'};$nodes[0].InnerText=$value;for($j=1;$j -lt $nodes.Count;$j++){$nodes[$j].InnerText=''}}
 function SetCentered($p,[bool]$keepNext){$pr=$p.SelectSingleNode('w:pPr',$ns);if(-not $pr){$pr=$doc.CreateElement('w','pPr',$w);$null=$p.PrependChild($pr)};foreach($old in @($pr.SelectNodes('w:keepNext|w:jc|w:pageBreakBefore',$ns))){$null=$pr.RemoveChild($old)};if($keepNext){$null=$pr.AppendChild($doc.CreateElement('w','keepNext',$w))};$jc=$doc.CreateElement('w','jc',$w);$null=$jc.SetAttribute('val',$w,'center');$null=$pr.AppendChild($jc);$sp=$pr.SelectSingleNode('w:spacing',$ns);if(-not $sp){$sp=$doc.CreateElement('w','spacing',$w);$null=$pr.AppendChild($sp)};$null=$sp.SetAttribute('before',$w,'0');$null=$sp.SetAttribute('after',$w,'0')}
 $doc=ReadXml 'word/document.xml';$rels=ReadXml 'word/_rels/document.xml.rels';$w='http://schemas.openxmlformats.org/wordprocessingml/2006/main';$a='http://schemas.openxmlformats.org/drawingml/2006/main';$r='http://schemas.openxmlformats.org/officeDocument/2006/relationships';$ns=[Xml.XmlNamespaceManager]::new($doc.NameTable);$ns.AddNamespace('w',$w);$ns.AddNamespace('a',$a);$ns.AddNamespace('r',$r);$ns.AddNamespace('wp','http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing')
 $body=$doc.SelectSingleNode('//w:body',$ns);$tables=$doc.SelectNodes('//w:body/w:tbl',$ns).Count;$dict=@($doc.SelectNodes('//w:body/w:tbl',$ns)|Select-Object -Skip 5);$fields=0;foreach($table in $dict){$fields+=$table.SelectNodes('w:tr',$ns).Count-1};if($tables -ne 23 -or $fields -ne 201){throw "Expected 23 tables and 201 dictionary fields; found $tables / $fields."}
 $paragraphs=@($body.SelectNodes('w:p',$ns));$pictureTemplate=@($paragraphs|Where-Object {(TargetOf $_) -eq 'media/summary-dfd.png'}|Select-Object -First 1)[0];$captionTemplate=@($paragraphs|Where-Object {(TextOf $_).Trim() -match '^Figure 3a\. (Level 1 DFD - Process|Complete Level 1 DFD - All Nine Processes)'}|Select-Object -First 1)[0];$securityCaption=@($paragraphs|Where-Object {(TextOf $_).Trim() -match '^Figure 3b\. User Login - Additional Individual Security Stores|^Figure 3j\. User Login - Additional Individual Security Stores'}|Select-Object -First 1)[0]
 if(-not $pictureTemplate -or -not $captionTemplate -or -not $securityCaption){throw 'Expected DFD image/caption templates or security supplement were not found.'};$pictureTemplate=$pictureTemplate.CloneNode($true);$captionTemplate=$captionTemplate.CloneNode($true)
 foreach($p in @($body.SelectNodes('w:p',$ns))){$text=(TextOf $p).Trim();$target=TargetOf $p;if($target -match '^media/dfd-process-[1-9]\.png$' -or $target -eq 'media/03-dfd-complete-one-page.png' -or $text -match '^Figure 3[a-i]\. Level 1 DFD - Process [1-9]\.0:' -or $text -eq 'Figure 3a. Complete Level 1 DFD - All Nine Processes' -or $text.StartsWith('The nine process panels')){$null=$body.RemoveChild($p)}}
 $paragraphs=@($body.SelectNodes('w:p',$ns));$securityCaption=@($paragraphs|Where-Object {(TextOf $_).Trim() -match '^Figure 3b\. User Login - Additional Individual Security Stores|^Figure 3j\. User Login - Additional Individual Security Stores'}|Select-Object -First 1)[0];if(-not $securityCaption){throw 'Security supplement caption was removed unexpectedly.'}
 $caption=$captionTemplate.CloneNode($true);SetText $caption 'Figure 3a. Complete Level 1 DFD - All Nine Processes';SetCentered $caption $true
 $picture=$pictureTemplate.CloneNode($true);SetCentered $picture $false;$blip=$picture.SelectSingleNode('.//a:blip',$ns);$rid='rIdDFDCompleteOnePage';foreach($old in @($rels.DocumentElement.ChildNodes|Where-Object Id -eq $rid)){$null=$rels.DocumentElement.RemoveChild($old)};$null=$blip.SetAttribute('embed',$r,$rid);$rel=$rels.CreateElement('Relationship',$rels.DocumentElement.NamespaceURI);$rel.SetAttribute('Id',$rid);$rel.SetAttribute('Type',$r+'/image');$rel.SetAttribute('Target','media/03-dfd-complete-one-page.png');$null=$rels.DocumentElement.AppendChild($rel);WriteBinary 'word/media/03-dfd-complete-one-page.png' $source
 $cx=[long](9.7*914400);$img=[Drawing.Image]::FromFile($source);$cy=[long]($cx*$img.Height/$img.Width);$img.Dispose();foreach($extent in $picture.SelectNodes('.//wp:extent|.//a:xfrm/a:ext',$ns)){$null=$extent.SetAttribute('cx',[string]$cx);$null=$extent.SetAttribute('cy',[string]$cy)};$docPr=$picture.SelectSingleNode('.//wp:docPr',$ns);$docPr.SetAttribute('name','Complete Level 1 DFD - all nine processes');$docPr.SetAttribute('descr','One-page Gane-Sarson Level 1 DFD. Nine numbered process lanes; external entities at left; individually named data stores at right; horizontal directional flows remain within their process lane.')
 # Keep the caption with the image on its own landscape page.
 $capPr=$caption.SelectSingleNode('w:pPr',$ns);if(-not $capPr){$capPr=$doc.CreateElement('w','pPr',$w);$null=$caption.PrependChild($capPr)};$pageBreak=$doc.CreateElement('w','pageBreakBefore',$w);$null=$capPr.AppendChild($pageBreak)
 $pPr=$picture.SelectSingleNode('w:pPr',$ns);if(-not $pPr){$pPr=$doc.CreateElement('w','pPr',$w);$null=$picture.PrependChild($pPr)};$sect=$doc.CreateElement('w','sectPr',$w);$pgSz=$doc.CreateElement('w','pgSz',$w);$null=$pgSz.SetAttribute('w',$w,'15840');$null=$pgSz.SetAttribute('h',$w,'12240');$null=$pgSz.SetAttribute('orient',$w,'landscape');$null=$sect.AppendChild($pgSz);$pgMar=$doc.CreateElement('w','pgMar',$w);foreach($kv in @{top='432';bottom='432';left='432';right='432';header='360';footer='360';gutter='0'}.GetEnumerator()){$null=$pgMar.SetAttribute($kv.Key,$w,$kv.Value)};$null=$sect.AppendChild($pgMar);$null=$pPr.AppendChild($sect)
 $null=$body.InsertBefore($caption,$securityCaption);$null=$body.InsertBefore($picture,$securityCaption)
 foreach($p in @($body.SelectNodes('w:p',$ns))){$text=(TextOf $p).Trim();if($text -match 'Figure 3j|Figures 3a-i|detailed DFD panels that follow'){$text=$text.Replace('Figure 3j','Figure 3b').Replace('Figures 3a-i','Figure 3a').Replace('The detailed DFD panels that follow preserve every individually named data store and the specific flows between actors, processes, and stores.','The complete Level 1 DFD on the following page shows all nine numbered processes, each with named stores and directional data flows contained within its own horizontal lane.');SetText $p $text}}
 if($doc.SelectNodes('//w:body/w:tbl',$ns).Count -ne $tables){throw 'The requirements/schema table count changed.'};$after=@($doc.SelectNodes('//w:body/w:tbl',$ns)|Select-Object -Skip 5);$afterFields=0;foreach($table in $after){$afterFields+=$table.SelectNodes('w:tr',$ns).Count-1};if($afterFields -ne $fields){throw 'The data dictionary field count changed.'}
 SaveXml 'word/document.xml' $doc;SaveXml 'word/_rels/document.xml.rels' $rels
}finally{$zip.Dispose()}
$lock=[IO.File]::Open($path,'Open','ReadWrite','None');$lock.Dispose();Copy-Item -LiteralPath $work -Destination $path -Force
"Inserted the complete nine-process single-page DFD; preserved $tables tables and $fields dictionary fields. Backup: $backup"
